create type public.user_role as enum ('super_admin','salesperson');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.user_role not null default 'salesperson',phone text,area text,daily_target integer not null default 20,active boolean not null default true,created_at timestamptz not null default now());
create table public.shops(id uuid primary key default gen_random_uuid(),name text not null,owner text,phone text,area text,category text,status text not null default 'interested' check(status in ('hot','interested','later','not_relevant')),notes text,assigned_to uuid references public.profiles(id) on delete set null,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());
create table public.visits(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,salesperson_id uuid references public.profiles(id) on delete set null,visit_date date not null default current_date,outcome text not null,notes text,created_at timestamptz not null default now());
create table public.followups(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,assigned_to uuid references public.profiles(id) on delete set null,due_date date not null,type text not null default 'call',status text not null default 'pending' check(status in ('pending','done')),notes text,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),shop_id uuid references public.shops(id) on delete set null,salesperson_id uuid references public.profiles(id) on delete set null,order_date date not null default current_date,total numeric(14,2) not null default 0,status text not null default 'draft',notes text,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.shops enable row level security;alter table public.visits enable row level security;alter table public.followups enable row level security;alter table public.orders enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='super_admin' and active=true); $$;
create policy "profiles read self or admin" on profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "shops read assigned or admin" on shops for select to authenticated using(public.is_admin() or assigned_to=auth.uid() or created_by=auth.uid());
create policy "shops insert authenticated" on shops for insert to authenticated with check(created_by=auth.uid() or public.is_admin());
create policy "shops update assigned or admin" on shops for update to authenticated using(public.is_admin() or assigned_to=auth.uid() or created_by=auth.uid()) with check(public.is_admin() or assigned_to=auth.uid() or created_by=auth.uid());
create policy "visits read own or admin" on visits for select to authenticated using(public.is_admin() or salesperson_id=auth.uid());
create policy "visits insert own" on visits for insert to authenticated with check(salesperson_id=auth.uid() or public.is_admin());
create policy "followups read own or admin" on followups for select to authenticated using(public.is_admin() or assigned_to=auth.uid());
create policy "followups insert own" on followups for insert to authenticated with check(assigned_to=auth.uid() or public.is_admin());
create policy "followups update own or admin" on followups for update to authenticated using(public.is_admin() or assigned_to=auth.uid()) with check(public.is_admin() or assigned_to=auth.uid());
create policy "orders read own or admin" on orders for select to authenticated using(public.is_admin() or salesperson_id=auth.uid());
create policy "orders insert own" on orders for insert to authenticated with check(salesperson_id=auth.uid() or public.is_admin());
create index shops_assigned_to_idx on shops(assigned_to);create index visits_salesperson_date_idx on visits(salesperson_id,visit_date);create index followups_assigned_due_idx on followups(assigned_to,due_date);
